files.content:
body {
  min-height: 100vh;
  margin: 0;
  padding: 45px;
  font-family: 'Open Sans', sans-serif;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

.block {
  width: 500px;
  margin: 0 auto;
  border: 2px solid black;
  padding: 10px;
  background-color: white;
}

.block__img {
  float: right;
  width: 250px;
  height: 200px;
  margin: 10px;
  object-fit: cover;
}

.block__colored {
  padding: 15px;
  color: white;
  background-color: #5f0dee;
}

.block__text {
  margin-bottom: 5px;
}

.clearfix {
  clear: both;
}
